// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address newRoundImpl) public {

        address owner = address(this);
        c.initialize();

        bool ok;
        try c.updateRoundImplementation(payable(newRoundImpl)) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.roundImplementation() == newRoundImpl);
        } else {
            assertTrue(newRoundImpl == address(0));
        }
    }
}
